insert into public.twelve_game_packs (format, pack, title, content, answers)
values
  ('trivia', 1, 'Holiday Trivia', '{"intro":"Ten questions about the season. No googling — Santa is watching.","questions":[{"prompt":"What are the names of Santa''s reindeer that start with D?","choices":["Dasher, Dancer, Donner","Dasher, Dolly, Donner","Dancer, Donner, Dobby","Dasher, Dancer, Dixie"]},{"prompt":"Which country started the tradition of the Christmas tree?","choices":["Norway","England","Canada","Germany"]},{"prompt":"In ''A Christmas Carol'', what is Scrooge''s first name?","choices":["Elias","Ezekiel","Edmund","Ebenezer"]},{"prompt":"How many gifts in total are given in ''The Twelve Days of Christmas''?","choices":["364","144","212","78"]},{"prompt":"What color are mistletoe berries?","choices":["Purple","Green","Red","White"]},{"prompt":"Which plant is known as the ''Christmas flower'' and comes from Mexico?","choices":["Poinsettia","Hellebore","Holly","Amaryllis"]},{"prompt":"In the movie ''Elf'', what are the four main food groups of elves?","choices":["Candy, candy canes, candy corn, syrup","Sugar, sprinkles, syrup, spice","Cookies, cocoa, candy, cake","Candy, gingerbread, marshmallows, syrup"]},{"prompt":"What is the best-selling single of all time, according to Guinness?","choices":["White Christmas","Silent Night","All I Want for Christmas Is You","Jingle Bell Rock"]},{"prompt":"Which beverage company''s ads helped popularize the modern red-suited Santa?","choices":["Schweppes","Pepsi","Dr Pepper","Coca-Cola"]},{"prompt":"What do people traditionally put on top of a Christmas tree?","choices":["A candy cane","A bell","A snowflake","A star or an angel"]}]}'::jsonb, '{"correct":[0,3,3,0,3,0,0,0,3,3]}'::jsonb),
  ('trivia', 2, 'Holiday Trivia: Round Two', '{"intro":"You''ve warmed up. Ten fresh questions, a little trickier.","questions":[{"prompt":"What was the first song broadcast from space, in 1965?","choices":["Silent Night","Deck the Halls","Here Comes Santa Claus","Jingle Bells"]},{"prompt":"In ''Home Alone'', where are the McCallisters flying to?","choices":["Rome","London","Miami","Paris"]},{"prompt":"Which reindeer was added to the team in a 1939 story?","choices":["Olive","Comet","Blitzen","Rudolph"]},{"prompt":"What is the Grinch''s dog called?","choices":["Rex","Max","Spot","Buddy"]},{"prompt":"In which country is it a tradition to eat KFC on Christmas Day?","choices":["Australia","Japan","South Korea","Brazil"]},{"prompt":"What is a ''yule log'' made of when it''s a dessert?","choices":["A fruit loaf","A frozen custard","A meringue tower","A rolled sponge cake"]},{"prompt":"Which city has a famous Christmas market called the Christkindlesmarkt?","choices":["Nuremberg","Prague","Zurich","Vienna"]},{"prompt":"Frosty the Snowman came to life thanks to what?","choices":["An old silk hat","A corncob pipe","A button nose","A magic scarf"]},{"prompt":"What''s the name of the Island of Misfit Toys'' ruler in ''Rudolph the Red-Nosed Reindeer''?","choices":["King Moonracer","Sir Toyland","King Frost","King Winterbolt"]},{"prompt":"How many points does a snowflake almost always have?","choices":["Four","Five","Six","Eight"]}]}'::jsonb, '{"correct":[3,3,3,1,1,3,0,0,0,2]}'::jsonb),
  ('emoji', 1, 'Holiday Emoji Decode', '{"intro":"Each emoji string is a holiday movie or song. Decode it!","questions":[{"prompt":"🏠 🙅 👦","choices":["Lonely This Christmas","No Place Like Home","The Holiday","Home Alone"]},{"prompt":"🧝 🍝 🍬","choices":["Elf","The Nutcracker","The Santa Clause","Jingle All the Way"]},{"prompt":"⛄ 🎩 ✨","choices":["Frosty the Snowman","The Snowman","Let It Snow","Winter Wonderland"]},{"prompt":"🔴 👃 🦌","choices":["Prancer","Here Comes Santa Claus","Rudolph the Red-Nosed Reindeer","Grandma Got Run Over by a Reindeer"]},{"prompt":"💚 😠 🎄 🏔️","choices":["Mountain Christmas","The Nightmare Before Christmas","Scrooged","How the Grinch Stole Christmas"]},{"prompt":"🚂 ❄️ 🎅","choices":["The Night Before Christmas","Last Train Home","Snow Train","The Polar Express"]},{"prompt":"🔔 🔔 🎸","choices":["Jingle Bell Rock","Rockin'' Around the Christmas Tree","Carol of the Bells","Silver Bells"]},{"prompt":"🤍 🎄 💭","choices":["I''ll Be Home for Christmas","White Christmas","Blue Christmas","Silent Night"]},{"prompt":"👶 🌟 🐑 🌙","choices":["Twinkle Twinkle Little Star","Starry Night","Away in a Manger","Silent Night"]},{"prompt":"🎃 🎄 💀","choices":["Halloweentown","Scrooged","The Nightmare Before Christmas","Spirited"]}]}'::jsonb, '{"correct":[3,0,0,2,3,3,0,1,3,2]}'::jsonb),
  ('emoji', 2, 'Emoji Decode: Round Two', '{"intro":"More emoji, more movies, more songs. Trust your gut.","questions":[{"prompt":"❤️ 🤷 ✈️ 🇬🇧","choices":["Notting Hill","The Holiday","Last Christmas","Love Actually"]},{"prompt":"👻 👻 👻 💰","choices":["Ghostbusters","A Christmas Carol","Haunted Holidays","Three Ghosts and a Banker"]},{"prompt":"🥜 🪖 🩰","choices":["The Nutcracker","Swan Lake","Toy Soldiers","Babes in Toyland"]},{"prompt":"🏃 🛒 🤖 🎁","choices":["Black Friday","Toy Story","Home Alone 2","Jingle All the Way"]},{"prompt":"🎅 📜 ⚖️","choices":["Miracle on 34th Street","The Santa Clause","Santa''s Law","Fred Claus"]},{"prompt":"🕯️ 🌉 😇 🏦","choices":["A Christmas Story","Holiday Inn","The Bishop''s Wife","It''s a Wonderful Life"]},{"prompt":"🔫 🐮 👓 ❄️","choices":["Christmas Vacation","Home Alone","A Christmas Story","Die Hard"]},{"prompt":"🚗 💡 🏠 🌲 🦌","choices":["National Lampoon''s Christmas Vacation","Deck the Halls","The Family Stone","Four Christmases"]},{"prompt":"🥁 👦 🎶","choices":["The Little Drummer Boy","Rum Pum Pum","Joy to the World","Do You Hear What I Hear?"]},{"prompt":"🛷 🐴 🔔 🌨️","choices":["Winter Wonderland","Sleigh Ride","Jingle Bells","Over the River and Through the Wood"]}]}'::jsonb, '{"correct":[3,1,0,3,0,3,2,0,0,1]}'::jsonb),
  ('two_truths', 1, 'Two Truths and a Tradition', '{"intro":"Each set has two real holiday traditions from around the world and one we made up. Spot the fake.","questions":[{"prompt":"Which tradition is made up?","choices":["In Finland, families hide a frozen herring in the garden for children to find on Christmas morning.","In Japan, a bucket of KFC is a popular Christmas dinner.","In Norway, people hide their brooms on Christmas Eve so witches can''t steal them."]},{"prompt":"Which tradition is made up?","choices":["In Caracas, Venezuela, people roller-skate to early-morning Christmas Mass.","In Portugal, children leave out a single sock filled with salt for the Three Kings'' horses.","In Iceland, 13 mischievous ''Yule Lads'' visit children in the nights before Christmas."]},{"prompt":"Which tradition is made up?","choices":["In Ukraine, people decorate trees with artificial spider webs for good luck.","In Scotland, the first person to see snow on Christmas Eve must sing a carol on the doorstep.","In Catalonia, a smiling log called Caga Tió is ''fed'' and then hit with sticks until it gives out sweets."]},{"prompt":"Which tradition is made up?","choices":["In Sweden, millions watch the same Donald Duck cartoon special every Christmas Eve at 3 PM.","In Denmark, the family that unwraps the most gifts must wash all the dishes on Boxing Day.","In the Czech Republic, single women toss a shoe over their shoulder to predict whether they''ll marry."]},{"prompt":"Which tradition is made up?","choices":["In Canada, people bury a candy cane in the snow and dig it up on New Year''s Day for luck.","In some American families, a pickle-shaped ornament is hidden in the tree and whoever finds it first gets a prize.","In Austria, a horned beast called Krampus roams the streets to scare naughty children."]},{"prompt":"Which tradition is made up?","choices":["In Guatemala, people sweep their homes and burn a pile of rubbish in ''La Quema del Diablo''.","In Greece, people place a lemon under their pillow on Christmas Eve to dream of the year ahead.","In the Philippines, the city of San Fernando holds a Giant Lantern Festival."]}]}'::jsonb, '{"correct":[0,1,1,1,0,1]}'::jsonb),
  ('two_truths', 2, 'Two Truths and a Tradition: Round Two', '{"intro":"Another lap around the world. Two of these are real. One is pure fiction.","questions":[{"prompt":"Which tradition is made up?","choices":["In Italy, a kindly witch named La Befana delivers gifts on January 5th.","In Belgium, children polish a spoon and leave it on the windowsill for Saint Nicholas to fill with honey.","In Poland, an extra place is set at the Christmas Eve table for an unexpected guest."]},{"prompt":"Which tradition is made up?","choices":["In Ireland, people race wheelbarrows full of holly through town on Christmas Eve.","In Ireland, a tall candle is placed in the window on Christmas Eve to welcome travelers.","In Mexico, Las Posadas re-enacts Mary and Joseph''s search for shelter over nine nights."]},{"prompt":"Which tradition is made up?","choices":["In the Netherlands, Sinterklaas arrives by steamboat in mid-November.","In Switzerland, people tie bells to their pets'' collars so Santa won''t trip over them.","In Australia, Christmas lunch is often a barbecue or seafood at the beach."]},{"prompt":"Which tradition is made up?","choices":["In England, families pull Christmas crackers that pop and hold paper crowns and jokes.","In England, the youngest family member must wear a paper crown upside down until dessert.","In Wales, a horse skull on a pole called the Mari Lwyd goes door to door with singers."]},{"prompt":"Which tradition is made up?","choices":["In Ethiopia, many people celebrate Christmas (Genna) on January 7th.","In Estonia, families visit the sauna together on Christmas Eve.","In Estonia, families leave a lit candle in the freezer to keep winter spirits happy."]},{"prompt":"Which tradition is made up?","choices":["In France, children leave carrots in their shoes for Santa''s reindeer to find in April.","In Provence, France, families serve thirteen desserts at Christmas.","In France, a feast called Le Réveillon is held late on Christmas Eve."]}]}'::jsonb, '{"correct":[1,0,1,1,2,0]}'::jsonb),
  ('lyrics', 1, 'Carol Fill-in-the-Blank', '{"intro":"Classic carols with a word missing. Sing it in your head (or out loud).","questions":[{"prompt":"Dashing through the snow, in a one-horse open ____","choices":["carriage","sleigh","sled","sleigh-bell"]},{"prompt":"Deck the halls with boughs of ____","choices":["holly","ivy","pine","berries"]},{"prompt":"Silent night, holy night, all is calm, all is ____","choices":["light","white","quiet","bright"]},{"prompt":"Joy to the world, the Lord is come! Let earth receive her ____","choices":["King","Child","song","light"]},{"prompt":"We wish you a merry Christmas and a happy ____ year","choices":["bright","good","New","glad"]},{"prompt":"O Christmas tree, O Christmas tree, how lovely are your ____","choices":["needles","branches","candles","ornaments"]},{"prompt":"Away in a manger, no crib for a ____","choices":["bed","babe","rest","head"]},{"prompt":"Good King Wenceslas looked out on the Feast of ____","choices":["Christmas","Stephen","Epiphany","Nicholas"]},{"prompt":"On the twelfth day of Christmas my true love gave to me: twelve drummers ____","choices":["playing","drumming","marching","piping"]},{"prompt":"Up on the housetop reindeer pause, out jumps good old Santa ____","choices":["himself","Nick","Claus","Kringle"]}]}'::jsonb, '{"correct":[1,0,3,0,2,1,0,1,1,2]}'::jsonb),
  ('lyrics', 2, 'Carol Fill-in-the-Blank: Round Two', '{"intro":"Deeper cuts this time. How well do you really know the verses?","questions":[{"prompt":"Hark! The herald angels sing, glory to the newborn ____","choices":["Child","Prince","Lord","King"]},{"prompt":"O come, all ye faithful, joyful and ____","choices":["victorious","jubilant","triumphant","radiant"]},{"prompt":"God rest ye merry, gentlemen, let nothing you ____","choices":["deny","delay","dismay","dissuade"]},{"prompt":"O little town of Bethlehem, how still we see thee ____","choices":["rest","glow","lie","sleep"]},{"prompt":"Angels we have heard on high, sweetly singing o''er the ____","choices":["plains","fields","town","hills"]},{"prompt":"The first Noel the angel did say was to certain poor shepherds in fields as they ____","choices":["slept","stayed","lay","prayed"]},{"prompt":"It came upon the midnight clear, that glorious song of ____","choices":["gold","joy","peace","old"]},{"prompt":"Here we come a-wassailing among the leaves so ____","choices":["bright","gold","white","green"]},{"prompt":"Jolly old Saint Nicholas, lean your ear this ____","choices":["day","way","night","time"]},{"prompt":"O holy night, the stars are brightly ____","choices":["burning","gleaming","glowing","shining"]}]}'::jsonb, '{"correct":[3,2,2,2,0,2,3,3,1,3]}'::jsonb),
  ('bingo', 1, 'Holiday Bingo', '{"intro":"Tap a square when it happens to you today. You have until the game closes, so come back and mark more. 3 points a square, 8 points a line.","squares":["Someone sings a carol out loud","You hear ''All I Want for Christmas Is You''","You see a house with blinking lights","Someone says ''It''s cold outside!''","You eat a cookie","You wrap a present","You spot an inflatable lawn decoration","You drink something hot","You see a Santa hat","Someone mentions their holiday plans","Tape gets stuck to itself","You see a candy cane","You watch part of a holiday movie","You see snow (real or fake)","Someone wears an ugly sweater","You say ''Happy Holidays'' to a stranger","You hear jingle bells","You see a wreath on a door","You find a stray bit of glitter","You check a gift off your list","You see someone carrying a big shopping bag","You smell pine or cinnamon","A pet does something festive","You text a holiday greeting"]}'::jsonb, null),
  ('bingo', 2, 'Holiday Bingo: Round Two', '{"intro":"A fresh card for a fresh day. Same rules: mark squares as they happen until the game closes.","squares":["You light a candle","Someone asks what you want for Christmas","You see a gingerbread house","You hear a holiday ad on TV or radio","You see a red bow","You find a gift you forgot you bought","You see a snowman (any kind)","Someone says ''Ho ho ho''","You eat something with peppermint","You see an Advent calendar","You put on cozy socks","You see a nativity scene","Someone hums a holiday tune","You get a holiday card","You untangle a string of lights","You see a reindeer decoration","Someone talks about the weather","You see an elf (decoration or costume)","You drink hot chocolate","You hear sleigh bells","You see tinsel","Someone mentions New Year''s resolutions","You share a treat with someone","You take a festive photo"]}'::jsonb, null),
  ('scavenger', 1, 'Holiday Scavenger Hunt', '{"intro":"The clock starts when you press Start. Find each item and snap a photo. Faster means more points: full speed bonus inside 10 minutes.","items":["Something red and something green together","An ornament","Something that sparkles","A mug you''d drink cocoa from","Something shaped like a star","A pair of cozy socks"]}'::jsonb, null),
  ('scavenger', 2, 'Scavenger Hunt: Round Two', '{"intro":"New list, same clock. Find, snap, go! Full speed bonus inside 10 minutes.","items":["A roll of wrapping paper or a gift bag","Something with a snowflake on it","A candle","Something that jingles","A cookie (bonus points for eating it after)","Something gold"]}'::jsonb, null),
  ('photo', 1, 'Photo Challenge', '{"intro":"Take your best shot. The host picks the winner after the day closes.","prompt":"Recreate your favorite holiday movie scene with whatever''s lying around the house.","tips":"Props are encouraged. Pets in costume are very encouraged."}'::jsonb, null),
  ('photo', 2, 'Photo Challenge: Round Two', '{"intro":"One photo, one winner, chosen by the host once the day closes.","prompt":"Show us the most festive corner of your home.","tips":"Lights on, lamps off. Good angles win hearts."}'::jsonb, null),
  ('wyr', 1, 'Holiday Would You Rather', '{"intro":"No wrong answers. Pick one of each, then see how the group split.","questions":[{"a":"Unwrap all your gifts on Christmas Eve","b":"Wait until Christmas morning"},{"a":"Have a white Christmas every year","b":"Have a beach Christmas every year"},{"a":"Only eat Christmas cookies for a week","b":"Never eat a Christmas cookie again"},{"a":"Be one of Santa''s elves","b":"Be one of Santa''s reindeer"},{"a":"Get one big gift","b":"Get lots of small gifts"},{"a":"Wear an ugly sweater to every event in December","b":"Wear a Santa hat to every event in December"},{"a":"Decorate in November","b":"Decorate the week before Christmas"},{"a":"Hear ''Jingle Bells'' on repeat all day","b":"Hear nothing but silence all December"}]}'::jsonb, null),
  ('wyr', 2, 'Would You Rather: Round Two', '{"intro":"Back for more. Answer all eight, then compare with the group.","questions":[{"a":"Wrap every present perfectly","b":"Shop for every present in one day"},{"a":"Spend the holidays in a snowy cabin","b":"Spend the holidays in a big city"},{"a":"Have real candles on your tree","b":"Have a tree that sings when you walk by"},{"a":"Eat turkey for every meal on Christmas","b":"Eat only desserts on Christmas"},{"a":"Be able to fly like Santa''s sleigh","b":"Be able to fit down any chimney"},{"a":"Get socks every Christmas forever","b":"Get a surprise every Christmas, good or bad"},{"a":"Watch the same holiday movie every year","b":"Watch a new one every year"},{"a":"Host the big family dinner","b":"Be the guest who brings dessert"}]}'::jsonb, null),
  ('speed_match', 1, 'Speed-Matching', '{"intro":"Match each character to their movie. The clock starts when you press Start: accuracy scores most, speed adds a bonus (full bonus inside 30 seconds).","left_label":"Character","right_label":"Movie","lefts":["Buddy","Kevin McCallister","Clark Griswold","Ralphie","George Bailey","Jack Skellington","Scott Calvin","Kris Kringle"],"rights":["The Santa Clause","The Nightmare Before Christmas","A Christmas Story","Miracle on 34th Street","Home Alone","Elf","Christmas Vacation","It''s a Wonderful Life"]}'::jsonb, '{"correct":[5,4,6,2,7,1,0,3]}'::jsonb),
  ('speed_match', 2, 'Speed-Matching: Round Two', '{"intro":"Match each holiday figure to what they''re known for. Clock starts on Start; full speed bonus inside 30 seconds.","left_label":"Who","right_label":"Known for","lefts":["Rudolph","Frosty","The Grinch","Ebenezer Scrooge","La Befana","Krampus","The Nutcracker","Cindy Lou Who"],"rights":["Delivering gifts on a broomstick","Three ghostly visitors","Being ''no more than two''","Battling the Mouse King","A glowing red nose","Coming to life with a magic hat","Stealing Christmas","Scaring naughty children"]}'::jsonb, '{"correct":[4,5,6,1,0,7,3,2]}'::jsonb),
  ('finale', 1, 'Finale Quiz', '{"intro":"Twelve questions pulled from everything you played this month."}'::jsonb, null)
